#!/usr/bin/env node
/**
 * Stamp the native shell version into the generated Android project.
 *
 * WHY THIS IS A SCRIPT AND NOT A COMMIT. `android/` is regenerated by every APK build
 * (`rm -rf android && npx cap add android`) and is gitignored, so a `versionCode` edited in the
 * repository would be thrown away before the build. The numbers therefore live in `package.json`,
 * which is committed and is also what the OTA publisher reads:
 *
 *   version       "1.1.0"  what the phone shows, and the bundle version that is published
 *   nativeVersion 2        the APK's `versionCode` — the number OTA's `native_min` compares against
 *
 * Bump `nativeVersion` only when the change cannot travel over the air (new plugin, permission,
 * manifest entry, dependency). Everything else stays on the same shell.
 */

import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const gradlePath = path.join(root, 'android/app/build.gradle');

if (!fs.existsSync(gradlePath)) {
  console.error('[ota] android/app/build.gradle is missing — run `npx cap add android` first');
  process.exit(1);
}

const versionName = String(pkg.version ?? '').trim();
const versionCode = Number(pkg.nativeVersion);

if (!/^[0-9]+\.[0-9]+\.[0-9]+/.test(versionName)) {
  console.error(`[ota] package.json version "${versionName}" is not a version`);
  process.exit(1);
}
if (!Number.isInteger(versionCode) || versionCode < 1) {
  console.error('[ota] package.json nativeVersion must be a positive integer (the APK versionCode)');
  process.exit(1);
}

let gradle = fs.readFileSync(gradlePath, 'utf8');

const codePattern = /(\n\s*versionCode\s+)(\d+)/;
const namePattern = /(\n\s*versionName\s+")([^"]*)(")/;

if (!codePattern.test(gradle) || !namePattern.test(gradle)) {
  console.error('[ota] could not find versionCode/versionName in android/app/build.gradle');
  process.exit(1);
}

gradle = gradle.replace(codePattern, `$1${versionCode}`);
gradle = gradle.replace(namePattern, `$1${versionName}$3`);

fs.writeFileSync(gradlePath, gradle);
console.log(`[ota] shell stamped: versionCode ${versionCode}, versionName "${versionName}"`);
